import React, { useState } from 'react';
import { taskAPI } from '../../services/api';

const CreateTask = ({ projectId, onTaskCreated, onCancel }) => {
  const [formData, setFormData] = useState({ 
    title: '', 
    description: '',
    priority: 'medium',
    due_date: ''
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    setError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!formData.title.trim()) {
      setError('Task title is required');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const taskData = {
        ...formData,
        project_id: projectId
      };
      
      const response = await taskAPI.create(taskData);
      onTaskCreated(response.data.task);
      setFormData({ 
        title: '', 
        description: '',
        priority: 'medium',
        due_date: ''
      });
    } catch (error) {
      setError(error.response?.data?.error || 'Failed to create task');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="create-task-form">
      <h3>Create New Task</h3>
      
      {error && <div className="error-message">{error}</div>}

      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label>Task Title *</label>
          <input
            type="text"
            name="title"
            value={formData.title}
            onChange={handleChange}
            required
            placeholder="What needs to be done?"
            disabled={loading}
          />
        </div>

        <div className="form-group">
          <label>Description</label>
          <textarea
            name="description"
            value={formData.description}
            onChange={handleChange}
            placeholder="Describe the task (optional)"
            rows="3"
            disabled={loading}
          />
        </div>

        <div className="form-row">
          <div className="form-group">
            <label>Priority</label>
            <select
              name="priority"
              value={formData.priority}
              onChange={handleChange}
              disabled={loading}
            >
              <option value="low">Low</option>
              <option value="medium">Medium</option>
              <option value="high">High</option>
            </select>
          </div>

          <div className="form-group">
            <label>Due Date</label>
            <input
              type="date"
              name="due_date"
              value={formData.due_date}
              onChange={handleChange}
              disabled={loading}
            />
          </div>
        </div>

        <div className="form-actions">
          <button 
            type="button" 
            className="btn btn-secondary"
            onClick={onCancel}
            disabled={loading}
          >
            Cancel
          </button>
          <button 
            type="submit" 
            className="btn btn-primary"
            disabled={loading}
          >
            {loading ? 'Creating...' : 'Create Task'}
          </button>
        </div>
      </form>
    </div>
  );
};

export default CreateTask;

// Emit real-time event
try {
  const io = getIO();
  io.to(`project_${project_id}`).emit('task_created', {
    task: task,
    projectId: project_id
  });
} catch (error) {
  console.error('Socket emit error:', error);
}

// Emit real-time event
try {
  const io = getIO();
  // Get project ID for this task
  db.get('SELECT project_id FROM tasks WHERE id = ?', [id], (err, task) => {
    if (!err && task) {
      io.to(`project_${task.project_id}`).emit('task_updated', {
        taskId: id,
        newStatus: status,
        projectId: task.project_id
      });
    }
  });
} catch (error) {
  console.error('Socket emit error:', error);
}
